import { LoggerType } from "@vendoo/common/logger2/constructor";
import { ExtensionV3InterceptRequestBodyCommand } from "@vendoo/common/messaging/connection/types";
import { getExtensionLogger } from "../../common/logger";

const injectInterceptor = (message: ExtensionV3InterceptRequestBodyCommand) => {
  // Add message params to page (through DOM - meta type/content)
  const messageMeta = document.createElement("meta");
  messageMeta.name = `VendooInterceptor_Message_${message.id}`;
  messageMeta.content = JSON.stringify(message);
  document.head.append(messageMeta);

  // Add patcher script to page (will read params and reply through DOM)
  const script = document.createElement("script");
  script.type = "text/javascript";
  script.src = chrome.runtime.getURL("scripts/patch.js");
  document.head.prepend(script);

  // Monitor DOM changes to get response and reply
};

const observeHeadNodes = (
  { logger }: { logger: LoggerType },
  {
    messageId,
    sendResponse,
  }: {
    messageId: string;
    sendResponse: (
      response: ExtensionV3InterceptRequestBodyCommand["result"]
    ) => void;
  }
) => {
  const callback = (
    mutationList: MutationRecord[],
    observer: MutationObserver
  ) => {
    for (const mutation of mutationList) {
      if (mutation.type !== "childList") continue;

      for (const node of mutation.addedNodes) {
        if (node.nodeName === "META" && node.nodeType === 1) {
          const element = node as HTMLElement;
          if (
            element.getAttribute("name") ===
            `VendooInterceptor_Result_${messageId}`
          ) {
            logger.debug("Request Intercepted. Sending response.", {
              messageId,
            });
            const metaContent = element.getAttribute("content") ?? "";
            const formData = JSON.parse(metaContent);
            sendResponse({
              requestBody: { formData },
            } as chrome.webRequest.WebRequestBodyDetails);
            observer.disconnect();
            return;
          }
        }
      }
    }
  };

  logger.debug("Setting up MutationObserver", { messageId });
  const observer = new MutationObserver(callback);
  const config = { attributes: false, childList: true, subtree: false };
  observer.observe(document.head, config);
};

const handleMessage = (
  message: ExtensionV3InterceptRequestBodyCommand,
  _sender: any,
  sendResponse: (
    response: ExtensionV3InterceptRequestBodyCommand["result"]
  ) => void
) => {
  const logger = getExtensionLogger("extensionContentScript")
    .extend("InterceptNetwork")
    .extend("MessageHandler")
    .trace({ messageId: message.id });

  if (message.name !== "INTERCEPT_REQUEST_BODY") {
    logger.debug("Invalid message received.");
    return false;
  }

  logger.debug("Valid message received. Processing...", message);

  // Injecting the interceptor script
  injectInterceptor(message);

  // Setting up MutationObserver to retrieve the intercepted data
  observeHeadNodes({ logger }, { messageId: message.id, sendResponse });

  // this tells Chrome that we'll use
  // sendResponse asynchronously
  // after this function finishes
  return true;
};

chrome.runtime.onMessage.addListener(handleMessage);
