// Utils
import {
  createLogHandler,
  createExceptionLogHandler,
  createWarningLogHandler,
} from "./utils/createLogHandler";

// Types
import {
  LoggerConfigType,
  LoggerTransportFnType,
  LogTraceType,
  LoggerHandlerDepsType,
  LogMetricIntakeType,
  MetricMetaTrackerType,
} from "./types";
import { attempt } from "./utils/attempt";

/**
 * Vendoo Logger
 */
const loggerHandlers = (
  transports: LoggerTransportFnType[],
  traces: LogTraceType = {},
  monitorCode?: string
) => {
  const ingestLog: LoggerTransportFnType = log =>
    void transports.map(fn => attempt(fn, log));
  /**
   * Returns new logger handlers with the new traces saved
   * Uses a proxy to extend original traces while keeping track of the
   * Root object pointer, allowing it to be modified in the future
   */
  const trace = (newTraces: LogTraceType) => {
    return loggerHandlers(transports, { ...traces, ...newTraces });
  };

  const extend = (fn: string) =>
    trace({ fn: [traces?.fn ?? "", fn].filter(Boolean).join("/") });

  const monitor = (code: string) => {
    return loggerHandlers(transports, traces, code) as Omit<
      ReturnType<typeof loggerHandlers>,
      "trace" | "monitor" | "track" | "extend" | "traces"
    >;
  };

  const deps: LoggerHandlerDepsType = {
    ingestLog,
    traces,
    monitorCode,
  };

  const metricIntake = createLogHandler<LogMetricIntakeType>(deps, "info");

  const metricTrack = (code: string, meta: MetricMetaTrackerType = {}) => {
    metricIntake(`[${code}] Metric input`, {
      vendooMetrics: {
        ...meta,
        code,
      },
    });
  };

  return {
    traces,
    /**
     * @deprecated please use trace instead
     */
    track: createLogHandler(deps, "track").bind(null, "Tracking: "),
    debug: createLogHandler(deps, "debug", "debug"),
    exception: createExceptionLogHandler(deps),
    warn: createWarningLogHandler(deps),
    info: createLogHandler(deps, "info"),
    /** Trace any value */
    trace,
    /** Standard way to define a logger for a certain feature or flow */
    extend,
    /**
     * @deprecated read this page instead <PAGETOBEDEFINED> to understand how you can create your own monitors
     */
    monitor,
    metric: {
      track: metricTrack,
    },
  };
};

/**
 * Vendoo logger constructor
 */
export const createLogger = (
  config: LoggerConfigType,
  traces?: LogTraceType
) => {
  // Init Transports
  const transports = config.transports.map(fn => fn(config));

  // Handlers for the different types of logs plus a trace fn
  return loggerHandlers(transports, traces);
};

export type LoggerType = ReturnType<typeof createLogger>;

export default createLogger;
