// Types
import {
  LogContextType,
  LogNonExceptionType,
  LogExceptionType,
  LevelTypes,
  LoggerHandlerDepsType,
} from "../types";
import safeStringify from "fast-safe-stringify";
import { RUNNING_PLATFORM } from "@vendoo/common/detect-platform";

export function createLogHandler<DebugProperties extends any = any>(
  deps: LoggerHandlerDepsType,
  level: LevelTypes,
  ctxProp?: "debug"
): (message: string, debug?: DebugProperties) => void;
export function createLogHandler<
  LogContextProperties extends LogContextType = LogContextType
>(
  deps: LoggerHandlerDepsType,
  level: LevelTypes,
  ctxProp?: "ctx"
): (message: string, ctx?: LogContextProperties) => void;
export function createLogHandler<
  LogContextProperties extends LogContextType = LogContextType
>(
  deps: LoggerHandlerDepsType,
  level: LevelTypes,
  ctxProp: "ctx" | "debug" = "ctx"
) {
  const { ingestLog, traces, monitorCode } = deps;
  // Return the handler for the log. This is what dev interact with
  return (message: string, ctx?: LogContextProperties) => {
    const log: LogNonExceptionType = {
      type: level,
      message: prepareMessage(message, monitorCode),
      date: Date.now(),
      traces,
      [ctxProp]: prepareLogContext(ctx),
    };
    // Send log to each transport
    ingestLog(log);
  };
}

// Exception are treated differently
// Handle exception logging
export const createExceptionLogHandler = (deps: LoggerHandlerDepsType) => {
  const { ingestLog, traces, monitorCode } = deps;
  // Return the handler for the log. This is what dev interact with
  return (error: Error, errorID: string, ctx?: LogContextType) => {
    // LogExceptionType
    const log: LogExceptionType = {
      type: "exception",
      e: error,
      errorID,
      date: Date.now(),
      traces: {
        ...traces,
        monitorCode,
      },
      ctx: prepareLogContext(ctx),
    };

    // Send log to each transport
    ingestLog(log);
  };
};

// Warning are treated differently
// Handle exception logging
export const createWarningLogHandler = (deps: LoggerHandlerDepsType) => {
  const { ingestLog, traces, monitorCode } = deps;
  // Return the handler for the log. This is what dev interact with
  return (message: string, ctx?: LogContextType, error?: Error) => {
    // LogExceptionType
    const log: LogNonExceptionType = {
      type: "warn",
      e: error,
      message: prepareMessage(message, monitorCode),
      date: Date.now(),
      traces,
      ctx: prepareLogContext(ctx),
    };

    // Send log to each transport
    ingestLog(log);
  };
};

const prepareMessage = (message: string, monitorCode?: string) =>
  monitorCode ? `[${monitorCode}] ${message}` : message;

const prepareLogContext = <CTX = LogContextType>(
  ctx?: CTX
): CTX | undefined => {
  if (!ctx) return ctx;
  try {
    if (RUNNING_PLATFORM === "react-native") {
      return JSON.parse(safeStringify(ctx));
    }
    return ctx;
  } catch (error) {
    return {
      vendooTip: "Failed to serialize object",
      stack: error?.stack,
      message: error?.message,
    } as any;
  }
};
