/**
 * Allows to force enable the console transport
 * by setting something to vendooDebug on localStorage
 *
 * eg. Force enable console transport (reload afterwards):
 * `localStorage.setItem("vendooDebug", "vendooDebug")`
 *
 * eg. Undo (reload afterwards):
 * `localStorage.removeItem("vendooDebug")`
 */
const hasConsoleTransportDebug = (() => {
  return Boolean(
    typeof window === "object" &&
      "localStorage" in window &&
      window.localStorage.getItem("vendooDebug")
  );
})();

export default hasConsoleTransportDebug;
