import isBrowser from "../isBrowser";

export const ansiReset = "\x1b[0m";
const ansiColors = {
  // foreground colors
  black: "\x1b[30m",
  red: "\x1b[31m",
  green: "\x1b[32m",
  yellow: "\x1b[33m",
  blue: "\x1b[34m",
  magenta: "\x1b[35m",
  cyan: "\x1b[36m",
  white: "\x1b[37m",
  // background colors
  bg_red: "\x1b[41m",
  bg_green: "\x1b[42m",
  bg_yellow: "\x1b[43m",
  bg_blue: "\x1b[44m",
  bg_magenta: "\x1b[45m",
  bg_cyan: "\x1b[46m",
  bg_white: "\x1b[47m",
};
const cssColors = {
  // foreground colors
  black: "color: black",
  red: "color: red",
  green: "color: green",
  yellow: "color: yellow",
  blue: "color: blue",
  magenta: "color: magenta",
  cyan: "color: cyan",
  white: "color: white",
  // background colors
  bg_red: "background: red",
  bg_green: "background: green",
  bg_yellow: "background: yellow",
  bg_blue: "background: blue",
  bg_magenta: "background: magenta",
  bg_cyan: "background: cyan",
  bg_white: "background: white",
};

type ColorOptionsType = keyof typeof cssColors | keyof typeof ansiColors;

export const getColor = (color: ColorOptionsType) => {
  if (isBrowser()) {
    return cssColors[color];
  } else {
    return ansiColors[color];
  }
};

// Color here should the string value from getColor
export const getColorBeforeMessage = (color: string) => {
  if (isBrowser()) {
    return "";
  } else {
    return color;
  }
};

// Color here should the string value from getColor
export const getColorAfterMessage = (color: string) => {
  if (isBrowser()) {
    return color;
  } else {
    return ansiReset;
  }
};
