// Types
import {
  TransportHandleLogType,
  TransportConfigType,
  LoggerTransportFnType,
  LevelExceptionType,
  LevelTypes,
  LoggerConfigType,
  InitTransportFnType,
  LogExceptionType,
  LogNonExceptionType,
} from "../../types";

export const levelMapper: {
  [key in LevelTypes | LevelExceptionType]: number;
} = {
  debug: 3,
  info: 2,
  warn: 1,
  track: 0,
  exception: 0,
};

/**
 * Creates Transport
 * C = Configure the expected transport configuration
 * I = Configure the returning value from the init fn
 */
export const createTransport = <C extends TransportConfigType, I = void>(
  onTransportInit: (config: C) => I,
  handleLog: TransportHandleLogType<C, I>
) => {
  // the fn that sets the transport config
  return function configTransport(transportConfig: C): InitTransportFnType {
    // the fn that runs in createLogger to init all transports
    return function initTransport(
      loggerConfig: LoggerConfigType
    ): LoggerTransportFnType {
      let postInit: I;
      // Run transport init only if nothing is set to silent
      if (!transportConfig.silent && !loggerConfig.silent) {
        postInit = onTransportInit(transportConfig);
      }

      // return fn each logger uses to sent the log
      return function loggerTransport(log) {
        if (shouldIgnoreLog(transportConfig, loggerConfig, log)) return;

        handleLog(log, {
          transport: transportConfig,
          logger: loggerConfig,
          init: postInit,
        });
      };
    };
  };
};

const shouldIgnoreLog = (
  tc: TransportConfigType,
  lc: LoggerConfigType,
  log: LogNonExceptionType | LogExceptionType
) => {
  if (lc.silent || tc.silent) return true;
  // Set level filters - default to show all
  const transportFilterLevel = levelMapper[tc.level ?? "debug"];
  const loggerFilterLevel = levelMapper[lc.level ?? "debug"];
  const logLevel = levelMapper[log.type];
  // If silent don't show logs
  // If current log type is higher than set filter level don't log
  if (logLevel > transportFilterLevel || logLevel > loggerFilterLevel) {
    return true;
  } else {
    return false;
  }
};
