// Service reference
// https://docs.datadoghq.com/logs/log_collection/javascript/?tab=npm
import {
  datadogLogs,
  LogsInitConfiguration,
  LogsEvent,
} from "@datadog/browser-logs";
import { Context, ContextValue } from "@datadog/browser-core";

import format from "./common/formats";

import { TransportConfigType } from "../types";
import { createTransport } from "./common/createTransport";
import { VendooError } from "@vendoo/common/errors/vendoo";
import { APP_VERSION } from "@vendoo/common/global-constants";

interface ConfigType extends TransportConfigType {
  datadog: LogsInitConfiguration;
  onError?: (error: unknown, context?: any) => void;
}

const datadogTransport = createTransport<
  ConfigType,
  { onError: ConfigType["onError"] }
>(
  config => {
    datadogLogs.init({
      forwardErrorsToLogs: true,
      sampleRate: 100,
      version: APP_VERSION,
      telemetrySampleRate: 0,
      proxy: "https://cdn.vendoo.co/ddpv2rum",
      ...config.datadog,
      beforeSend,
    });
    return {
      onError: config.onError ?? (() => {}),
    };
  },
  (log, { init }) => {
    const metadata: Context = {};

    if (log.ctx) {
      metadata.ctx = log.ctx;
    }
    if (log.traces) {
      metadata.traces = log.traces;
      if (metadata.traces.fn) {
        metadata.logger = { name: String(metadata.traces.fn) };
      }
    }
    if (log.debug) {
      metadata.debug = log.debug;
    }
    if (log.e) {
      const errorValue = {
        ...log.e,
        stack: log.e?.stack,
        message: log.e?.message,
        name: log.e?.name,
      } as ContextValue;
      metadata.error = errorValue;
    }

    switch (log.type) {
      case "debug":
      case "info":
      case "warn":
        datadogLogs.logger[log.type](format.boston(log).join(" "), metadata);
        return;
      case "exception":
        metadata.errorID = log.errorID;

        if (log.e instanceof VendooError && !log.e.options?.alertTeam) {
          datadogLogs.logger.warn(format.boston(log).join(" "), metadata);
        } else {
          datadogLogs.logger.error(format.boston(log).join(" "), metadata);
          init.onError?.(log.e, metadata);
        }
        return;
    }
  }
);

const beforeSend = (event: LogsEvent): boolean | void => {
  try {
    if (window["__allowDebug"] && event.status === "debug") {
      return false;
    }
  } catch (_error) {
    /* */
  }
  if (event.error?.origin === "network" && event.http && event.http.url) {
    const url = event.http.url;
    // log any vendoo url
    if (/https:\/\/([a-z]+\.)?vendoo\.co/i.test(url)) return true;

    // remove facebook XHR errors from tracking. Add blockers block this URL and it's not an error
    if (
      url.includes("facebook.com/tr") ||
      url.includes("doubleclick.net") ||
      url.includes("cloudflareinsights.com") ||
      url.includes("cdnbasket.net") ||
      url.includes("braintreegateway.com") ||
      url.includes("pinterest.com") ||
      url.includes("cdnwidget.com") ||
      url.includes("yimg.com") ||
      url.includes("clarity.ms") ||
      url.includes("braze.com")
    ) {
      return false;
    }
  }
};

export default datadogTransport;
