/**
 * File to format log messages into a easy to read strings.
 * Start reading this file from the bottom. It will be easier
 * to understand.
 */

import { LogType } from "../../../types";
import isBrowser from "../isBrowser";
import { getColor, ansiReset } from "./colors";
/**
 * Create equal white space for better readability after the message type
 *
 * [info]      message +30ms
 * [exception] message +30ms
 * [debug]     message +30ms
 */
const createFormatType = (type: string) => {
  const l = type.length;
  const m = 6;
  const s = Array.from({ length: m - l }, () => "");
  return `[${type}]${s.join(" ")}`;
};

// Header
const type = (log: LogType) => createFormatType(log.type);
type.getColor = (log: LogType) => {
  switch (log.type) {
    case "debug":
      return getColor("green");
    case "info":
      return getColor("blue");
    case "warn":
      return getColor("bg_yellow");
    case "exception":
      return getColor("red");
    case "track":
      return getColor("black");
  }
};
// Message
const message = (log: LogType) => log.message || log.e?.message || "";
message.getColor = (_log: LogType) => {
  return "";
};

// ErrorID
const eid = (log: LogType) => (log.errorID ? `(err: ${log.errorID})` : "");
eid.getColor = (_log: LogType) => {
  return getColor("red");
};
// Iso Date
const iso = (log: LogType) => new Date(log.date).toISOString();
iso.getColor = (_log: LogType) => {
  return getColor("bg_yellow");
};
// Traces
const traces = (log: LogType) => {
  if (!log.traces) return "";

  // Print out all the traces. [ user=bob ]
  return `[ ${Object.keys(log.traces).reduce((acc, key) => {
    if (!log.traces || !log.traces[key]) return acc;
    return acc + `${key}=${log.traces[key]} `;
  }, "")}]`;
};

traces.getColor = (_log: LogType) => {
  return getColor("magenta");
};

// Create message
// Take the log and an array of fns to create the message
const create = (
  log: LogType,
  arr: {
    (log: LogType): string;
    getColor(log: LogType): string;
  }[],
  color?: boolean
) => {
  let message: string[] = [];

  // loop thru and add to the message string
  arr.forEach(fn => {
    // Format the current part of the message
    let part = fn(log);
    // Get color for the part
    const colorValue = fn.getColor(log);

    // On node we wrap the parts with the color
    // format with color. Part could be an empty string
    if (!isBrowser() && color && part) {
      message.push(colorValue);
    }

    // Add %c to color code in the browser
    if (part && color && isBrowser()) part = "%c " + part;
    // push formatted part to the message
    if (part) {
      message.push(part);
    }

    // On node we end with color reset
    // format with color. Part could be an empty string
    if (!isBrowser() && color && part) {
      message.push(ansiReset);
    }
  });

  if (color && isBrowser()) {
    // In the browser we need to concat the values in one string
    // to color the string correctly
    message = [message.join(" ")];
    // add colors to the end
    arr.forEach(fn => {
      // Format the current part of the message
      let part = fn(log);
      const colorValue = fn.getColor(log);
      if (part) {
        message.push(colorValue);
      }
    });
  }

  // return final log message
  return message;
};

// Why are we using names of cities?
// Because naming things is hard, we want don't want to think
// too much into the name of each different format. It doesn't matter
// what the name is. The important thing is we know what the output
// will be. Read the JSDoc for each format to know the output
export default {
  /**
   * Output the log with the following parts in the following order;
   * - [type] message diff errorID traces
   *
   * **Example:**
   * - [warn] this is a message +23ms (err: zk8j8H1hSMgC) [ user=bob ]
   *
   * @param {LogType} log - The log to format
   * @param {boolean} color - Optional param to format with color values.
   * **This should only be used with a console transport.**
   * @returns {Array.<string>} An array of the string. **Be sure to either join or spread the values.**
   */
  paris: (log: LogType, color?: boolean) =>
    create(log, [type, message, eid, traces], color),
  /**
   * Output the log with the following parts in the following order;
   * - [type] message diff iso_date errorID
   *
   * **Example:**
   * - [warn] this is a message +23ms 2020-10-22T01:37:22.671Z (err: zk8j8H1hSMgC)
   *
   * @param {LogType} log - The log to format
   * @param {boolean} color - Optional param to format with color values.
   * **This should only be used with a console transport.**
   * @returns {Array.<string>} An array of the string. **Be sure to either join or spread the values.**
   */
  london: (log: LogType, color?: boolean) =>
    create(log, [type, message, iso, eid], color),
  /**
   * Output the log with the following parts in the following order;
   * - [type] message
   *
   * **Example:**
   * - [warn] this is a message
   *
   * @param {LogType} log - The log to format
   * @param {boolean} color - Optional param to format with color values.
   * **This should only be used with a console transport.**
   * @returns {Array.<string>} An array of the string. **Be sure to either join or spread the values.**
   */
  baltimore: (log: LogType, color?: boolean) =>
    create(log, [type, message], color),

  /**
   * Output the log with the following parts in the following order;
   * - [type] message errorID traces
   *
   * **Example:**
   * - [warn] this is a message (err: zk8j8H1hSMgC) [ user=bob ]
   *
   * @param {LogType} log - The log to format
   * @param {boolean} color - Optional param to format with color values.
   * **This should only be used with a console transport.**
   * @returns {Array.<string>} An array of the string. **Be sure to either join or spread the values.**
   */
  miami: (log: LogType, color?: boolean) =>
    create(log, [type, message, eid, traces], color),

  /**
   * Output the log with the following parts in the following order;
   * - message
   *
   * **Example:**
   * - this is a message
   *
   * @param {LogType} log - The log to format
   * @param {boolean} color - Optional param to format with color values.
   * **This should only be used with a console transport.**
   * @returns {Array.<string>} An array of the string. **Be sure to either join or spread the values.**
   */
  boston: (log: LogType, color?: boolean) => create(log, [message], color),
};
