import { DISABLE_EXTERNAL_LOGGING_TOOLS } from "@vendoo/common/global-constants";
import datadogTransport from "@vendoo/common/logger2/transports/datadog";

export const extensionDatadogTransport = datadogTransport({
  // Hide on local and on Tests
  silent: DISABLE_EXTERNAL_LOGGING_TOOLS,
  datadog: {
    clientToken: process.env.DATADOG_CLIENT_TOKEN!,
    env: process.env.GATSBY_WORK_ENV,
    site: "datadoghq.com",
    service: "extension",
    forwardErrorsToLogs: false,
    ...(process.env.GATSBY_WORK_ENV === "local"
      ? {}
      : {
          trackSessionAcrossSubdomains: true,
          useSecureSessionCookie: true,
          useCrossSiteSessionCookie: true,
        }),
  },
});
