/* eslint-disable no-console */
import { createTransport } from "./common/createTransport";
import { LogNonExceptionType } from "../types";
import isBrowser from "./common/isBrowser";
import format from "./common/formats";
import { getPlatform } from "@vendoo/common/detect-platform";

/**
 * this is needed just for the ts check to work when testing node packages
 */
declare function alert(message?: any): void;

const isNode = () => getPlatform() !== "browser";

const formatConsoleData = (log: LogNonExceptionType) => {
  const data: { [k: string]: {} } = {
    data: { ...(log.debug ?? {}), ...(log.ctx ?? {}) },
  };

  if (!isNode() && log.traces && Object.keys(log.traces))
    data["trace"] = { ...log.traces };

  let message = log.message;

  if (log.message.length > 120) {
    data["msg"] = { message };
    message = message.slice(0, 120) + "...";
  }
  return { data, message };
};

const consoleTransport = createTransport(
  () => {},
  log => {
    switch (log.type) {
      case "debug":
      case "info":
      case "warn": {
        const { message, data } = formatConsoleData(log);
        const formatter = isNode() ? format.paris : format.baltimore;
        return console[log.type](...formatter({ ...log, message }, true), data);
      }
      case "exception": {
        console.error(
          ...format.miami(log, true),
          log.ctx ? log.ctx : "",
          "\n",
          log.e.stack
        );
        if (
          isBrowser() &&
          alert &&
          (process.env.GATSBY_WORK_ENV === "dev" ||
            process.env.GATSBY_WORK_ENV === "local")
        ) {
          alert(
            "[Unhandled Error] \n" +
              log.e.message +
              "\nAll unhandled errors should be turned into VendooErrors"
          );
        }
        return;
      }
      case "track": {
        return console.info(...format.paris(log, true), log.ctx);
      }
    }
  }
);

export default consoleTransport;
