export const APP_VERSION =
  process.env.CIRCLE_TAG ||
  (process.env.CIRCLE_SHA1 || "").substring(0, 7) ||
  process.env.GATSBY_WORK_ENV;

export const IS_LOCAL_ENV = process.env.GATSBY_WORK_ENV === "local";

export const IS_PROD_ENV =
  process.env.GATSBY_WORK_ENV === "prod" &&
  process.env.NODE_ENV === "production";

export const IS_TEST_ENV = process.env.NODE_ENV === "test";

export const DISABLE_EXTERNAL_LOGGING_TOOLS = IS_LOCAL_ENV || IS_TEST_ENV;
