import { IS_LOCAL_ENV, IS_TEST_ENV } from "@vendoo/common/global-constants";

import createLogger from "@vendoo/common/logger2/constructor";
import consoleTransport from "@vendoo/common/logger2/transports/console";
import hasConsoleTransportDebug from "@vendoo/common/logger2/utils/hasConsoleTransportDebug";

import getExtensionVersion from "../get-extension-version";

import { extensionDatadogTransport } from "./extensionDatadogTransport";

export const traces = {
  get extVersion() {
    return getExtensionVersion();
  },
  vendooApplication: "extensionBackgroundScript",
};

export const getExtensionLogger = (vendooApplication: string) => {
  traces.vendooApplication = vendooApplication;

  return createLogger(
    {
      transports: [
        consoleTransport({
          silent:
            IS_TEST_ENV || (hasConsoleTransportDebug ? false : !IS_LOCAL_ENV),
        }),
        extensionDatadogTransport,
      ],
    },
    traces
  );
};
