// Credit: https://github.com/visionmedia/debug/blob/master/src/index.js#L6
const isBrowser = () =>
  Boolean(
    typeof process === "undefined" ||
      // @ts-ignore
      process.type === "renderer" ||
      // @ts-ignore
      typeof window !== "undefined" ||
      // @ts-ignore
      process.__nwjs
  );

export default isBrowser;
