import { HandledErrorType } from "@vendoo/common/errors/handle";

type baseTypes = string | number | boolean | undefined | null;

/** Extra data to track during logs */
export type VendooErrorCtxType = { [id: string]: baseTypes | baseTypes[] };

export interface ErrorOptions {
  /**
   * True for handled exceptions that the user can retry the last action.
   */
  allowRetry: boolean;
  /**
   * Handled exceptions that are important enough to alert us every time.
   */
  alertTeam: boolean;
  /**
   * Http code to return from server-side API
   */
  httpCode: number;

  errorID?: string;
  monitorCode?: string;
}

/**
 * Customized Error class useful for passing along
 * extra data with the default Error stack data.
 *
 * Normal use case is throwing the VendooError with
 * the extra data and reading that extra data in a
 * catch handler
 */
export class VendooError extends Error {
  public isVendoo = true;
  public name = "VendooError";
  public options: ErrorOptions;

  /**
   * If you need to rethrow the error to raise a runtime exception,
   * then you can use this function after you called handleException
   */
  static fromHandledErrorType(
    err: HandledErrorType,
    /**
     * Forces to set alertTeam option on the VendooError
     *
     * Usually when recovering from a HandledErrorType
     * it means that the error has already been alerted.
     * in this case, we can rebuild the error with this set to false
     */
    alertTeam = false
  ): VendooError {
    if (!err.errorID)
      throw new Error(
        "fromHandledErrorType Error: Provided error object is not a HandledErrorType"
      );
    return new VendooError(
      err.rawMessage,
      {
        alertTeam: alertTeam,
        allowRetry: err.allowRetry,
        errorID: err.errorID,
        httpCode: err.httpCode,
      },
      err.context
    );
  }

  /**
   * Creates a Vendoo as usual, but adding context
   * about the original raised error to help debugging
   */
  public static fromError(
    error: Error,
    message: string,
    options: Partial<ErrorOptions> = {},
    ctx?: VendooErrorCtxType
  ): VendooError {
    if (error instanceof VendooError) {
      const origins = Array.isArray(error.ctx?.originalErrorMessageHistory)
        ? error.ctx.originalErrorMessageHistory
        : [];

      return new VendooError(
        message,
        { ...error.options, ...options },
        {
          ...error.ctx,
          ...ctx,
          originalErrorMessageHistory: [error.message, ...origins],
        }
      );
    }

    return new VendooError(
      message,
      options,
      Object.assign({}, ctx, {
        originalErrorMessage: error.message,
        originalErrorStack: error.stack,
        originalErrorName: error.name,
      })
    );
  }

  constructor(
    message: string,
    options: Partial<ErrorOptions> = {},
    public ctx?: VendooErrorCtxType
  ) {
    super(message);
    this.options = Object.assign(
      {
        allowRetry: false,
        alertTeam: false,
        httpCode: 500,
      },
      options
    );
  }
}

/**
 * Used to represent Multiple errors that might arise during async processes
 * Also used to handle the possibility of more than one error set on the listing attempts
 */
export class MixedError extends Error {
  static multipleErrorsMessagePrefix = "Multiple errors received";

  static getErrorMessages(errors: Error[]) {
    return errors.map(
      e => `
  - ${e.message}`
    );
  }

  static toString(errors: Error[]) {
    const errorMessages = MixedError.getErrorMessages(errors);
    return `${MixedError.multipleErrorsMessagePrefix}: ${errorMessages}`;
  }

  constructor(public errors: Error[]) {
    super(MixedError.toString(errors));
    this.name = "MixedError";
  }

  toString() {
    return `${this.message}
  - Stack: ${this.stack}`;
  }
}
